// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(address adr, bytes calldata data, uint256 value) public {
        vm.assume(adr != address(0) && adr != address(c));
        vm.deal(address(c), 10 ether);
        uint256 balanceBefore = address(c).balance;
        bool ok;
        vm.prank(c.Owner());
        try c.Command{value: value}(adr, data) { ok = true; } catch { ok = false; }
        uint256 balanceAfter = address(c).balance;
        if (ok) {
            assertTrue(balanceAfter == balanceBefore);
        } else {
            assertTrue(true);
        }
    }
}
